style.css:
@-moz-document url-prefix("https://www.linuxfromscratch.org/") {
/* Immediate dark background to prevent white flash */
    html, body {
        background-color: #0a0a0f !important;
        color: #e4e4e7 !important;
    }
    
    /* Hide content until userscript loads */
    body {
        visibility: hidden !important;
    }
    
    /* Basic dark styling for common elements */
    * {
        background-color: transparent !important;
        color: inherit !important;
        border-color: #2a2a3e !important;
    }
    
    /* Override white backgrounds */
    [style*="background-color: white"],
    [style*="background-color: #fff"],
    [style*="background-color: #ffffff"] {
        background-color: #151520 !important;
    }
}
